<template id="item-template"><div class="withdraw-item border rounded p-3 mb-2"><div class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label">ประเภทการเบิก</label><select class="form-select item-type" required></select><input type="hidden" class="item-type-id"></div><div class="col-md-2"><label class="form-label">Lead Time</label><div class="form-control bg-light item-lead">-</div></div><div class="col-md-2"><label class="form-label">วันที่แนะนำ</label><div class="form-control bg-light item-recommended">-</div></div><div class="col-md-2"><label class="form-label">วันที่ต้องเบิก</label><input type="date" class="form-control item-date" required></div><div class="col-md-2"><label class="form-label">หมายเหตุ</label><input class="form-control item-remark"></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger remove-item">ลบ</button></div></div></div></template>
<script>
document.addEventListener('DOMContentLoaded',()=>{const types=@json($types->map(fn($t)=>['id'=>$t->id,'name'=>$t->name,'lead'=>$t->lead_time_days])->values());const items=document.getElementById('items');const subtract=(text,days)=>{if(!text)return'';const d=new Date(text+'T00:00:00');while(days>0){d.setDate(d.getDate()-1);if(d.getDay()!==0)days--;}return d.toISOString().slice(0,10)};const renumber=()=>document.querySelectorAll('.withdraw-item').forEach((r,i)=>{r.querySelector('.item-type-id').name=`items[${i}][type_id]`;r.querySelector('.item-date').name=`items[${i}][planned_withdraw_date]`;r.querySelector('.item-remark').name=`items[${i}][remark]`});const recalc=r=>{const t=types.find(x=>String(x.id)===r.querySelector('.item-type').value),date=subtract(document.getElementById('production_date').value,t?.lead||0);r.querySelector('.item-lead').textContent=t?`${t.lead} วันทำงาน`:'-';r.querySelector('.item-recommended').textContent=date||'-';if(!r.querySelector('.item-date').value)r.querySelector('.item-date').value=date;r.querySelector('.item-type-id').value=t?.id||''};const add=()=>{const r=document.getElementById('item-template').content.firstElementChild.cloneNode(true),s=r.querySelector('.item-type');s.innerHTML='<option value="">เลือกประเภท</option>'+types.map(t=>`<option value="${t.id}">${t.name}</option>`).join('');s.addEventListener('change',()=>recalc(r));r.querySelector('.remove-item').addEventListener('click',()=>{r.remove();renumber()});items.appendChild(r);renumber();recalc(r)};document.getElementById('add-item').addEventListener('click',add);document.getElementById('production_date').addEventListener('change',()=>document.querySelectorAll('.withdraw-item').forEach(r=>{r.querySelector('.item-date').value='';recalc(r)}));add();new TomSelect('#mfg-lookup',{valueField:'id',labelField:'text',searchField:['text'],maxItems:1,create:false,loadThrottle:300,load(q,cb){if(q.length<1)return cb();fetch(`{{ route('stock-withdrawal.mfg-search') }}?q=${encodeURIComponent(q)}&limit=20`).then(r=>r.json()).then(j=>cb(j.results||[])).catch(()=>cb())},render:{option(d,e){return `<div><strong>${e(d.meta.site)} · ${e(d.id)}</strong><div class="small text-muted">${e(d.meta.partnumber||'')} · ${e(d.meta.customer_name||'-')} · ส่ง ${e(d.meta.due_date||'-')}</div></div>`},item(d,e){return `<div>${e(d.meta.site)} · ${e(d.id)}</div>`}},onChange(v){const d=this.options[v]?.meta;if(!d)return;document.getElementById('site').value=String(d.site||'').toUpperCase()==='WIRE'?'WIRE':'PLUS';document.getElementById('workorder_id').value=d.workorder_id||'';document.getElementById('show-mfg').textContent=v;document.getElementById('show-size').textContent=d.size||d.area_label||'-';document.getElementById('show-quantity').textContent=`${d.wo_qty??'-'} ${d.unit||''}`;document.getElementById('show-customer').textContent=d.customer_name||'-';document.getElementById('show-delivery').textContent=d.due_date||'-';document.getElementById('show-note').textContent=d.wo_notes||d.plan_description||'-';document.getElementById('save-btn').disabled=false}})});
</script>
